function lastStoneWeight(stones) {
  const s = [...stones].sort((a, b) => a - b);   // sort once, lightest first
  while (s.length > 1) {
    const y = s.pop(), x = s.pop();              // the two heaviest are at the end
    if (y === x) continue;
    const d = y - x;
    let lo = 0, hi = s.length;                   // binary search for where d belongs
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (s[mid] < d) lo = mid + 1; else hi = mid;
    }
    s.splice(lo, 0, d);                          // insert it there: shifts up to n stones
  }
  return s.length ? s[0] : 0;
}

import bisect

def last_stone_weight(stones):
    s = sorted(stones)                           # sort once, lightest first
    while len(s) > 1:
        y, x = s.pop(), s.pop()                  # the two heaviest are at the end
        if y != x:
            bisect.insort(s, y - x)              # binary search + insert: shifts up to n stones
    return s[0] if s else 0

int lastStoneWeight(int[] stones) {
    List<Integer> s = new ArrayList<>();
    for (int x : stones) s.add(x);
    Collections.sort(s);                               // sort once, lightest first
    while (s.size() > 1) {
        int y = s.remove(s.size() - 1);                // the two heaviest are at the end
        int x = s.remove(s.size() - 1);
        if (y == x) continue;
        int d = y - x;
        int lo = 0, hi = s.size();                     // binary search for where d belongs
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (s.get(mid) < d) lo = mid + 1; else hi = mid;
        }
        s.add(lo, d);                                  // insert it there: shifts up to n stones
    }
    return s.isEmpty() ? 0 : s.get(0);
}

