}

import heapq

def last_stone_weight(stones):
    heap = [-s for s in stones]              # negate: heapq is a min-heap
    heapq.heapify(heap)                      # O(n)
    while len(heap) > 1:
        y = -heapq.heappop(heap)             # the heaviest
        x = -heapq.heappop(heap)             # the second heaviest
        if y != x:
            heapq.heappush(heap, -(y - x))   # the difference survives
    return -heap[0] if heap else 0

int lastStoneWeight(int[] stones) {
    PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());   // max-heap
    for (int s : stones) heap.offer(s);
    while (heap.size() > 1) {
        int y = heap.poll();                 // the heaviest
        int x = heap.poll();                 // the second heaviest
        if (y != x) heap.offer(y - x);       // the difference survives
    }
    return heap.isEmpty() ? 0 : heap.peek();
}

int lastStoneWeight(vector<int>& stones) {
    priority_queue<int> heap(stones.begin(), stones.end());   // a max-heap, built in O(n)
    while (heap.size() > 1) {
        int y = heap.top(); heap.pop();      // the heaviest
        int x = heap.top(); heap.pop();      // the second heaviest
        if (y != x) heap.push(y - x);        // the difference survives
    }
    return heap.empty() ? 0 : heap.top();
}
